import React from "react";
import { useNavigate } from "react-router-dom";
import Navbar from "../components/Navbar";

function NonTechnicalEvents() {
  const navigate = useNavigate();

  const events = [
    { id: 1, name: "Adzap", time: "9:30 AM - 12:30 PM", venue: "Room 121" },
    {
      id: 2,
      name: "Just a Minute",
      time: "1:00 PM - 4:30 PM",
      venue: "Room 115",
    },
    {
      id: 3,
      name: "Best Manager",
      time: "1:00 PM - 4:30 PM",
      venue: "Room 113",
    },
    {
      id: 4,
      name: "Connections",
      time: "10:00 AM - 12:00 PM",
      venue: "Room 110",
    },
    {
      id: 5,
      name: "Treasure Hunt",
      time: "10:30 AM - 1:30 PM",
      venue: "Campus Area",
    },
    { id: 6, name: "Debate", time: "2:00 PM - 4:00 PM", venue: "Seminar Hall" },
    {
      id: 7,
      name: "Group Discussion",
      time: "11:00 AM - 1:00 PM",
      venue: "Room 108",
    },
    { id: 8, name: "Mime", time: "9:00 AM - 11:00 AM", venue: "Auditorium" },
    { id: 9, name: "Photography", time: "All Day", venue: "Entire Campus" },
    {
      id: 10,
      name: "Short Film",
      time: "2:00 PM - 5:00 PM",
      venue: "Room 105",
    },
    { id: 11, name: "Quiz", time: "12:00 PM - 2:00 PM", venue: "Room 102" },
    {
      id: 12,
      name: "Stress Interview",
      time: "3:00 PM - 5:00 PM",
      venue: "Room 101",
    },
  ];

  const handleRegister = (event) => {
    navigate("/register", {
      state: {
        eventId: event.id,
        eventName: event.name,
      },
    });
  };

  return (
    <div>
      <Navbar />
      <h2 style={{ textAlign: "center" }}>Non-Technical Events</h2>

      <div style={{ display: "grid", gap: "20px", padding: "20px" }}>
        {events.map((event) => (
          <div
            key={event.id}
            style={{ border: "1px solid #ccc", padding: "15px" }}
          >
            <h3>{event.name}</h3>
            <p>
              <b>Time:</b> {event.time}
            </p>
            <p>
              <b>Venue:</b> {event.venue}
            </p>

            <button onClick={() => handleRegister(event)}>Register</button>
          </div>
        ))}
      </div>
    </div>
  );
}

export default NonTechnicalEvents;
